<div class="page-heading"><div><div class="eyebrow">TRANSAKSI PENGHASILAN</div><h1><?=e($title)?><span class="heading-dot">.</span></h1><p>Periksa kehadiran dan setiap komponen sebelum menyimpan.</p></div><a href="<?=url('transaksi',['bulan'=>(int)$values['bulan'],'tahun'=>$values['tahun']])?>" class="btn btn-light">Kembali ke daftar</a></div>
<?php if($error):?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif;?><div id="calculation-message" class="alert alert-info" role="status" hidden></div>
<form id="payroll-form" method="post" action="<?=e(url('transaksi/form'))?>" class="payroll-form" data-record-id="<?=$id?>" data-calculation-version="<?=e($before['calculation_version']??'accounting_v2')?>"><input type="hidden" name="confirmation_token" value="<?=e($confirmationToken??'')?>"><input type="hidden" name="warnings_accepted" value="0"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="surface mb-4"><div class="panel-header"><h2>Konteks transaksi</h2><?php if($before && $before['source']==='legacy'):?><span class="soft-badge">Transaksi historis</span><?php endif;?></div><div class="panel-body"><div class="row g-3"><div class="col-md-3"><label class="form-label" for="form-month">Bulan</label><select class="form-select" id="form-month" name="bulan" <?=$id?'disabled':''?>><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>"<?=selected((int)$values['bulan'],$m)?>><?=month_name($m)?></option><?php endfor;?></select><?php if($id):?><input type="hidden" name="bulan" value="<?=(int)$values['bulan']?>"><?php endif;?></div><div class="col-md-2"><label class="form-label" for="form-year">Tahun</label><input class="form-control" id="form-year" type="number" min="1900" max="9999" name="tahun" value="<?=e($values['tahun'])?>" required <?=$id?'readonly':''?>></div><div class="col-md-4"><label class="form-label" for="form-department">Bagian</label><select class="form-select" id="form-department" name="bagian" required <?=$id?'disabled':''?>><option value="">Pilih bagian</option><?php foreach($departments as $d):?><option value="<?=e($d['kd_bagian'])?>"<?=selected($department,$d['kd_bagian'])?>><?=e($d['nama_bagian'])?></option><?php endforeach;?></select><?php if($id):?><input type="hidden" name="bagian" value="<?=e($department)?>"><?php endif;?></div><div class="col-md-3"><label class="form-label" for="calculation-mode">Perhitungan</label><select class="form-select" id="calculation-mode" name="calculation_mode"><option value="manual"<?=selected($mode,'manual')?>>Nilai komponen transaksi</option><option value="master"<?=selected($mode,'master')?>>Hitung dari master saat ini</option></select></div><div class="col-md-5"><label class="form-label" for="employee-nip">NIP karyawan</label><div class="picker-field"><input class="form-control" id="employee-nip" name="nip" maxlength="15" required value="<?=e($values['nip']??'')?>" <?=$id?'readonly':''?>><?php if(!$id):?><button type="button" class="btn btn-light" data-bs-toggle="modal" data-bs-target="#employee-picker"><?=icon('search')?> Cari</button><?php endif;?></div></div><div class="col-md-7"><label class="form-label" for="employee-name">Nama karyawan</label><input class="form-control" id="employee-name" name="employee_name" value="<?=e($employeeName)?>" readonly></div></div></div></div>
<div class="payroll-grid"><div><section class="surface mb-4"><div class="panel-header"><h2>Kehadiran & jumlah kegiatan</h2><span class="panel-icon"><?=icon('calendar')?></span></div><div class="panel-body"><div class="attendance-grid"><?php foreach(App\Domain\PayrollFields::ATTENDANCE as $field=>$label):?><div><label class="form-label" for="payroll-<?=e($field)?>"><?=e($label)?></label><input class="form-control text-end" id="payroll-<?=e($field)?>" name="<?=e($field)?>" type="text" inputmode="numeric" maxlength="18" pattern="[0-9]{1,18}" value="<?=e($values[$field]??'')?>" data-payroll-value <?=$field==='hefektif'?'required':''?>></div><?php endforeach;?></div><button class="btn btn-light mt-4" id="load-components" type="button"><?=icon('arrow-right')?> Muat komponen master</button><div class="form-text mt-2">Tarif harian dan lembur berasal dari master karyawan. Konsumsi, infal, dan overtime mengikuti master bagian. Potongan lain-lain dari master mengisi potongan satu kali; tunjangan lain tetap penghasilan manual. Untuk histori, nilai tersimpan menjadi acuan sampai Anda memilih hitung ulang.</div></div></section>
<section class="surface mb-4"><details class="panel-body"><summary class="fw-semibold">Dasar perhitungan dan sumber tarif</summary><p class="muted-small mt-3">Tunjangan harian = tarif karyawan ? hari efektif. Konsumsi = tarif bagian ? masuk kerja. Lembur, infal, dan overtime = tarif masing-masing ? jumlah kegiatan. Potongan absensi mengikuti aturan lama: tarif harian ? (izin/alpha + 0,5 ? sakit). Nominal dibulatkan per komponen sebelum dijumlahkan. BJBS/BPJS memakai nominal master; belum ada perhitungan persentase otomatis.</p><div id="rate-sources" class="muted-small"><?php if($before && empty($before['calculation_snapshot'])):?>Tarif historis tidak direkonstruksi; nominal transaksi tersimpan tetap menjadi acuan.<?php else:?>Rincian sumber tarif akan tampil setelah perhitungan master berhasil.<?php endif;?></div></details></section>
<div class="payroll-columns"><section class="surface"><div class="panel-header"><h2>Penghasilan</h2><span class="component-icon component-0 mb-0"><?=icon('plus')?></span></div><div class="panel-body"><?php foreach(App\Domain\PayrollFields::INCOME as $field=>$label):?><div class="payroll-field"><label for="payroll-<?=e($field)?>"><?=e($label)?></label><div class="input-group"><span class="input-group-text">Rp</span><input class="form-control text-end" id="payroll-<?=e($field)?>" name="<?=e($field)?>" inputmode="numeric" pattern="-?[0-9]{1,18}" maxlength="19" value="<?=e($values[$field]??'')?>" data-payroll-value></div></div><?php endforeach;?></div></section><section class="surface"><div class="panel-header"><h2>Potongan</h2><span class="component-icon component-2 mb-0"><?=icon('minus')?></span></div><div class="panel-body"><?php foreach(App\Domain\PayrollFields::DEDUCTIONS as $field=>$label):?><div class="payroll-field"><label for="payroll-<?=e($field)?>"><?=e($label)?></label><div class="input-group"><span class="input-group-text">Rp</span><input class="form-control text-end" id="payroll-<?=e($field)?>" name="<?=e($field)?>" inputmode="numeric" pattern="-?[0-9]{1,18}" maxlength="19" value="<?=e($values[$field]??'')?>" data-payroll-value></div></div><?php endforeach;?></div></section></div></div><aside class="surface total-panel"><div class="panel-header"><h2>Ringkasan penghasilan</h2><?=icon('wallet')?></div><div class="panel-body"><p id="calculation-status" class="muted-small" role="status"><?=$id?'Nilai transaksi tersimpan.':'Perhitungan diperiksa kembali sebelum penyimpanan.'?></p><div class="total-row"><span>Penghasilan bruto</span><strong data-total="tpenghasilan"><?=money($values['tpenghasilan']??0)?></strong></div><div class="total-row"><span>Total potongan</span><strong data-total="tpotongan"><?=money($values['tpotongan']??0)?></strong></div><div class="net-total"><small>PENGHASILAN BERSIH</small><strong data-total="tbersih"><?=money($values['tbersih']??0)?></strong></div><button type="submit" class="btn btn-primary"><?=icon('save')?> Simpan penghasilan</button><?php if($id):?><a class="btn btn-light" href="<?=url('laporan',['type'=>'slip_karyawan','nip'=>$values['nip'],'bulan'=>(int)$values['bulan'],'tahun'=>$values['tahun'],'view'=>1])?>"><?=icon('print')?> Pratinjau slip</a><?php endif;?><a class="btn btn-light" href="<?=url('transaksi',['bulan'=>(int)$values['bulan'],'tahun'=>$values['tahun']])?>">Batal</a><div class="form-note"><?=icon('shield')?><span>Perhitungan diperiksa kembali di server ketika transaksi disimpan.</span></div></div></aside></div></form>
